class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Calculates the negative log-probability of the final token in each sequence.

        Hypothesis for future: This detector assumes that hallucinations are
        more likely to be finalized with higher confidence (lower negative log-prob)
        than ground-truth facts, as the model may overfit to the false pattern.
        """
        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            # seq_logprobs length is n_i - 1. The last element corresponds to the 
            # probability of the final token (index n_i - 2 in the sequence).
            if len(seq_logprobs) > 0:
                final_neg_logprob = -seq_logprobs[-1]
            else:
                final_neg_logprob = 0.0
            scores.append(final_neg_logprob)
        return np.array(scores, dtype=np.float32)
# Score achieved with the function above: 50.0

class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        # "sequence_logprobs": List[np.ndarray] of length N, inner 1d array has length n_i - 1.
        # MUST return shape [N] where N = number of samples
        total_neg_logprob = np.array([-np.sum(sequence_logprobs) for sequence_logprobs in stats["sequence_logprobs"]], dtype=np.float32)
        return total_neg_logprob

# Score achieved with the function above: 74.3286
